from typing import List

class Solution:
    def atMostNGivenDigitSet(self, digits: List[str], n: int) -> int:
        s = str(n)
        k = len(s)
        m = len(digits)
        ans = sum(m ** i for i in range(1, k))

        for i, ch in enumerate(s):
            smaller = sum(d < ch for d in digits)
            ans += smaller * (m ** (k - 1 - i))
            if ch not in digits:
                return ans
        return ans + 1

