public:
    int atMostNGivenDigitSet(vector<string>& digits, int n) {
        string s = to_string(n);
        int k = s.length();
        int m = digits.size();
        int ans = 0;
        int p = m;
        for (int i = 1; i < k; i++) {
            ans += p;
            p *= m;
        }
        for (int i = 0; i < k; i++) {
            char ch = s[i];
            int smaller = 0;
            bool match = false;
            for (string& d : digits) {
                if (d[0] < ch) smaller++;
                else if (d[0] == ch) match = true;
            }
            int rem = 1;
            for (int j = 0; j < k - 1 - i; j++) rem *= m;
            ans += smaller * rem;
            if (!match) return ans;
        }
        return ans + 1;
    }
};

