var atMostNGivenDigitSet = function(digits, n) {
    const s = String(n);
    const k = s.length;
    const m = digits.length;
    let ans = 0;
    for (let i = 1; i < k; i++) {
        ans += m ** i;
    }
    for (let i = 0; i < k; i++) {
        const ch = s[i];
        const smaller = digits.filter(d => d < ch).length;
        ans += smaller * (m ** (k - 1 - i));
        if (!digits.includes(ch)) return ans;
    }
    return ans + 1;
};
